DECLARE
    V_9          SYS_REFCURSOR;
    V_10         SYS_REFCURSOR;
    V_CUR        INTEGER;
    V_COLS       INTEGER;
    V_DESC       DBMS_SQL.DESC_TAB2;
    V_ROWS       NUMBER;
    V_T0         NUMBER;
    V_T1         NUMBER;
    V_T2         NUMBER;
BEGIN
    V_T0 := DBMS_UTILITY.GET_TIME;
    PKG_SCP0007.P_SCP0007_GET_BOD(
        P_DIVISION_ID => '40'
      , P_FROM_SITE => 'AZ00-E'
      , P_TO_SITE => 'ALL'
      , P_INCOTERMS => 'ALL'
      , P_INCOTERMS_SSP => 'ALL'
      , P_TRANS_MODE => 'ALL'
      , P_INPUT_STATUS => 'C'
      , P_VALID_YN => ''
      , O_RC => V_9
      , O_RESULT_CURSOR => V_10
    );
    V_T1 := DBMS_UTILITY.GET_TIME;
    BEGIN
        V_ROWS := 0;
        V_CUR := DBMS_SQL.TO_CURSOR_NUMBER(V_9);
        DBMS_SQL.DESCRIBE_COLUMNS2(V_CUR, V_COLS, V_DESC);
        WHILE DBMS_SQL.FETCH_ROWS(V_CUR) > 0 LOOP
            V_ROWS := V_ROWS + 1;
        END LOOP;
        DBMS_SQL.CLOSE_CURSOR(V_CUR);
        DBMS_OUTPUT.PUT_LINE('V_9 ROWS = ' || V_ROWS || ' , COLS = ' || V_COLS);
    EXCEPTION
        WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('V_9 열리지 않음 : ' || SQLERRM);
    END;
    BEGIN
        V_ROWS := 0;
        V_CUR := DBMS_SQL.TO_CURSOR_NUMBER(V_10);
        DBMS_SQL.DESCRIBE_COLUMNS2(V_CUR, V_COLS, V_DESC);
        WHILE DBMS_SQL.FETCH_ROWS(V_CUR) > 0 LOOP
            V_ROWS := V_ROWS + 1;
        END LOOP;
        DBMS_SQL.CLOSE_CURSOR(V_CUR);
        DBMS_OUTPUT.PUT_LINE('V_10 ROWS = ' || V_ROWS || ' , COLS = ' || V_COLS);
    EXCEPTION
        WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('V_10 열리지 않음 : ' || SQLERRM);
    END;
    V_T2 := DBMS_UTILITY.GET_TIME;
    DBMS_OUTPUT.PUT_LINE('PROC_SEC  = ' || TO_CHAR((V_T1 - V_T0) / 100, 'FM9999990.00'));
    DBMS_OUTPUT.PUT_LINE('FETCH_SEC = ' || TO_CHAR((V_T2 - V_T1) / 100, 'FM9999990.00'));
    DBMS_OUTPUT.PUT_LINE('TOTAL_SEC = ' || TO_CHAR((V_T2 - V_T0) / 100, 'FM9999990.00'));
END;

